import process from "node:process";
import AxeBuilder from "@axe-core/playwright";
import { expect, test } from "@playwright/test";
import { createClient } from "@supabase/supabase-js";
import { waitForEmail } from "./support/mailbox";
import { createUser, signIn, uniqueEmail } from "./support/users";

// What every ticket of the increment builds on: the sign-up plumbing, the
// test helpers, and the app shell they all inherit. Owned by the Contracts
// ticket; feature tickets do not edit this file.

const AXE_TAGS = ["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa"];

function env(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`${name} must be set. Run \`pnpm bootstrap\`.`);
  return value;
}

test("a sign-up creates the profile and email destination, and its link returns to this origin", async ({
  baseURL,
}) => {
  const url = env("NEXT_PUBLIC_SUPABASE_URL");
  const anonymous = createClient(
    url,
    env("NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"),
    {
      auth: { persistSession: false, autoRefreshToken: false },
    },
  );
  const email = uniqueEmail("contracts");

  const { data, error } = await anonymous.auth.signUp({
    email,
    password: "a-long-enough-password",
    options: { emailRedirectTo: `${baseURL}/auth/confirm` },
  });
  expect(error).toBeNull();
  const userId = data.user?.id;
  expect(userId).toBeTruthy();

  const message = await waitForEmail(email, "Confirm your Heads-up account");
  const link = message.links.find((href) => href.includes("token_hash="));
  expect(link, "the confirmation link carries a token hash").toBeTruthy();
  expect(link).toContain(`${baseURL}/auth/confirm?token_hash=`);
  expect(link).toContain("type=email");

  const admin = createClient(url, env("SUPABASE_SECRET_KEY"), {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const profile = await admin
    .from("profiles")
    .select("email, role")
    .eq("user_id", userId ?? "");
  expect(profile.data).toEqual([{ email, role: "user" }]);
  const destinations = await admin
    .from("destinations")
    .select("channel_type, name, status")
    .eq("user_id", userId ?? "");
  expect(destinations.data).toEqual([
    { channel_type: "email", name: "Account email", status: "active" },
  ]);
});

test("a created admin signs in, sees the Admin link, and the shell passes the accessibility scan", async ({
  page,
  isMobile,
}) => {
  const admin = await createUser({ admin: true });
  await signIn(page, admin);
  await expect(
    page.getByRole("heading", { level: 1, name: "Alerts" }),
  ).toBeVisible();
  // The title streams in after a client-side navigation: scan only once it is there.
  await expect(page).toHaveTitle("Alerts · Heads-up");

  if (isMobile) {
    const closed = await new AxeBuilder({ page }).withTags(AXE_TAGS).analyze();
    expect(closed.violations).toEqual([]);

    await page.getByRole("button", { name: "Menu" }).click();
    await expect(page.getByRole("link", { name: "Admin" })).toBeVisible();
    await expect(page.getByRole("link", { name: "Alerts" })).toHaveAttribute(
      "aria-current",
      "page",
    );
  } else {
    await expect(page.getByRole("link", { name: "Admin" })).toBeVisible();
    await expect(page.getByText(admin.email)).toBeVisible();
  }

  const results = await new AxeBuilder({ page }).withTags(AXE_TAGS).analyze();
  expect(results.violations).toEqual([]);
});

test("a created user does not see the Admin link and can sign out", async ({
  page,
  isMobile,
}) => {
  const user = await createUser();
  await signIn(page, user);

  if (isMobile) await page.getByRole("button", { name: "Menu" }).click();
  await expect(page.getByRole("link", { name: "Admin" })).toHaveCount(0);

  await page.getByRole("button", { name: "Sign out" }).click();
  await expect(page).toHaveURL(/\/$/);

  await page.goto("/alerts");
  await expect(page).toHaveURL(/\/sign-in\?next=%2Falerts/);
});
